// ---- Quality lab (t-qual): shared helpers. Data in window.QD (33_js_q_0data.js, generated by src/qual/q_make_data.py) ----
window.QL=(function(){
  const RM=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
  const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const TAB='t-qual';
  const onRender=f=>{(window.TAB_RENDER=window.TAB_RENDER||{});(window.TAB_RENDER[TAB]=window.TAB_RENDER[TAB]||[]).push(f)};
  const visible=()=>{const t=document.getElementById(TAB);return t&&!t.hidden&&t.offsetParent!==null};
  const onResize=f=>{let t=0;addEventListener('resize',()=>{if(!visible())return;clearTimeout(t);t=setTimeout(f,80)})};
  const width=el=>{const w=el&&el.clientWidth;return w&&w>40?w:Math.max(280,Math.min(860,(document.documentElement.clientWidth||900)-60))};
  const cv=n=>getComputedStyle(document.documentElement).getPropertyValue(n).trim()||'#888';
  const fmt=(x,d)=>(x==null||!isFinite(x))?'n/a':Number(x).toLocaleString('en-GB',{maximumFractionDigits:d==null?0:d,minimumFractionDigits:d==null?0:d});
  const pct=(x,d)=>fmt(100*x,d==null?1:d)+'%';
  // step-animation controller: play, pause, step, scrub, speed; animates only on screen in the visible tab
  function anim(o){ // 2026-11-09: the skill template RD.anim (21_js_rd_common.js): plays once at least half in view, pauses off screen, stops for good on any control or at its last step,
    // never moves by itself under reduced motion; o.auto false makes it a widget that never plays by itself. Redrawn when this tab opens.
    if(!o.fast)o.ms=Math.max(o.ms||0,3800); // time to read each step's caption
    const A=RD.anim(o);onRender(()=>A.redraw());return A}
  // statistics used by several views
  function ranks(a){const ix=a.map((v,i)=>i).sort((x,y)=>a[x]-a[y]);const r=new Array(a.length);
    let i=0;while(i<ix.length){let j=i;while(j+1<ix.length&&a[ix[j+1]]===a[ix[i]])j++;const m=(i+j)/2;for(let k=i;k<=j;k++)r[ix[k]]=m;i=j+1}return r}
  function pearson(x,y){const n=x.length;let mx=0,my=0;for(let i=0;i<n;i++){mx+=x[i];my+=y[i]}mx/=n;my/=n;
    let sxy=0,sxx=0,syy=0;for(let i=0;i<n;i++){const a=x[i]-mx,b=y[i]-my;sxy+=a*b;sxx+=a*a;syy+=b*b}return sxy/Math.sqrt(sxx*syy)}
  const spearman=(x,y)=>pearson(ranks(x),ranks(y));
  // top-k sets: indices of the k highest values
  const topk=(a,k)=>{const ix=a.map((v,i)=>i).sort((x,y)=>a[y]-a[x]);return new Set(ix.slice(0,k))};
  function overlap(A,B){let i=0;A.forEach(v=>{if(B.has(v))i++});const u=A.size+B.size-i;return {inter:i,union:u,jacc:u?i/u:0}}
  const seg=(el,f)=>el.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!el.contains(b))return;el.querySelectorAll('button').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});f(b.dataset.m)});
  const svg=(w,h,body,label)=>'<svg viewBox="0 0 '+w+' '+h+'" width="'+w+'" height="'+h+'" role="img" aria-label="'+esc(label||'')+'">'+body+'</svg>';
  const T=(x,y,s,o)=>{o=o||{};return '<text x="'+x+'" y="'+y+'"'+(o.a?' text-anchor="'+o.a+'"':'')+' font-size="'+(o.fs||11)+'"'+(o.fill?' fill="'+o.fill+'"':' fill="var(--mute)"')+(o.w?' font-weight="'+o.w+'"':'')+'>'+s+'</text>'};
  return {RM,esc,onRender,onResize,width,cv,fmt,pct,anim,ranks,spearman,pearson,topk,overlap,seg,svg,T,visible};
})();
